export function createSynthesisState(){return {config:null,generation:0,mode:'plan',inputs:null,workflow:null,result:null,plan:null,verified:null,encoding:null};}
export function invalidateSynthesisState(s){s.generation++;for(const n of ['inputs','workflow','result','plan','verified','encoding'])s[n]=null;}
export const isCurrentSynthesisOperation=(s,g,c,a)=>s.generation===g&&c===a;
export function handoffSynthesizedRoot(document,v){check(v?.records?.outputVerified===true&&v.records.clientPlanOnly===true&&v.records.transactionExecuted===false&&v.records.networkSubmitted===false&&v.root?.owner===v.actor&&v.root.lifecycle===0&&v.root.artifactIdHex===v.workflow?.artifactIdHex&&v.root.target===v.workflow.target&&v.root.schema===(v.workflow.target<=15?2:v.workflow.target<=21?3:4)&&v.root.descriptorHex===descriptor(v.workflow.target),'请先核验实际、可用的合成成品。');handoffKnownAsset(document,{actor:v.actor,instanceHex:v.root.instanceHex});}

